-- Generated by `mbm settings apply` from ~/.config/mbm/settings.json over the
-- shipped defaults. Do not edit: change settings (or the defaults) instead.

hl.bind("SUPER + RETURN", hl.dsp.exec_cmd("uwsm app -- $TERMINAL"), { description = "Terminal" })
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("qs -c mbm ipc call osd volume +5"), { description = "Volume up", locked = true, repeating = true })
hl.bind("SUPER + SPACE", hl.dsp.exec_cmd("qs -c mbm ipc call launcher toggle"), { description = "Launcher" })
hl.bind("ALT + TAB", function() hl.dispatch(hl.dsp.window.cycle_next()) hl.dispatch(hl.dsp.window.bring_to_top()) end, { description = "Focus on next window" })
hl.bind("SUPER + mouse:273", hl.dsp.window.resize(), { description = "Resize window" })
hl.bind("SUPER + code:10", hl.dsp.focus({ workspace = 1 }), { description = "Switch to workspace 1" })

-- Key recording in the settings window: an empty submap, so every key reaches
-- the window. SUPER+CTRL+ALT+Escape always gets out (e.g. if the shell died).
hl.define_submap("mbm-record", function() hl.bind("SUPER + CTRL + ALT + Escape", hl.dsp.submap("reset")) end)
